import { Group, Mesh, PlaneGeometry, MeshBasicNodeMaterial } from 'three/webgpu';
import { gsap } from 'gsap';
import { primitives } from '@/primitives';
import { text } from '@/text';

/**
 * @typedef {Object} NodeConfig
 * @property {string} [imageUrl]
 * @property {Array<Object>} [textContent]
 * @property {Object} [intent]
 * @property {Object} [intent.visualSpec]
 * @property {Array<Object>} [cinematicPrimitives]
 * @property {Object} [colors]
 */

/**
 * @typedef {Object} NodeContext
 * @property {Object} THREE
 * @property {Object} textureLoader
 * @property {Object} fontAtlas
 * @property {Object} primitives
 * @property {Function} emit
 * @property {string} [tier]
 */

export default function createNode(config, ctx) {
  // Root container
  const root = new Group();

  // ---- Plane (hero subhead) ----
  const planeGeom = new PlaneGeometry(1, 1);
  const planeMat = new MeshBasicNodeMaterial({
    transparent: true,
    depthWrite: false,
  });
  const planeMesh = new Mesh(planeGeom, planeMat);
  root.add(planeMesh);

  // Load texture asynchronously
  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      planeMat.map = tex;
      planeMat.needsUpdate = true;
    });
  }

  // ---- Text content ----
  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  for (const item of items) {
    const txt = ctx.fontAtlas.createText(item.text, {
      fontSize: item.typography?.fontSize || 42,
      color: (config.colors?.paper) || '#e8ecf2',
      align: 'center',
    });
    // Position text slightly in front of the plane
    txt.position.set(0, 0, 0.01);
    root.add(txt);
  }

  // ---- Apply cinematic primitives (if any) ----
  const cleanups = [];
  if (Array.isArray(config.cinematicPrimitives)) {
    for (const prim of config.cinematicPrimitives) {
      const fn = ctx.primitives[prim.name];
      if (typeof fn === 'function') {
        const instance = fn(root, prim.params);
        if (instance?.cleanup) cleanups.push(instance.cleanup);
        // handlers are attached via userData later
      }
    }
  }

  // ---- Event handlers placeholder ----
  root.userData.handlers = {};

  // ---- Cleanup routine ----
  root.userData.cleanup = () => {
    // Dispose material and geometry
    planeMat.dispose();
    planeGeom.dispose();

    // Dispose any textures attached to material (three.js will handle via texture loader cache)
    // Kill GSAP timelines if any were created
    gsap.globalTimeline.clear();

    // Run primitive cleanups
    for (const fn of cleanups) fn();
  };

  return root;
}
